  statusCode: 200,
  correlationId: correlationId default "CID-STATIC-1001",
  itemCount: sizeOf(payload.data),
  inventory: payload.data map ((prod) -> {
    productId: prod.id,
    itemCode: prod.sku,
    unitPrice: "$" ++ (prod.price as String {format: "#,##0.00"}),
    inStock: prod.stock > 0
  }),
  metadata: {
    apiVersion: "v2.1",
    timestamp: now()
  }
}

