script:
%dw 2.0
output application/json
---
{
  tariffRate: if (payload.meterType == "RESIDENTIAL") 0.12
              else if (payload.meterType == "COMMERCIAL") 0.18
              else 0.25,
  accountAction: payload.paymentStatus match {
    case "PAID" -> "STANDARD_SERVICE"
    case "OVERDUE" -> "DISPATCH_SMS_REMINDER"
    case "DEFAULTED" -> "SHUTOFF_NOTICE"
    else -> "REVIEW_REQUIRED"
  },
  tier: if (payload.kwhUsage > 1000) "HIGH_CONSUMPTION" else "STANDARD"
}

