script:
%dw 2.0
output application/json
---
payload.customer ++ payload.billing ++ {
  lastUpdated: now() as String {format: "yyyy-MM-dd"}
}

%dw 2.0
output application/json
var totalPages = ceil(payload.totalRecords / payload.pageSize)
---
{
  pagination: {
    pageNumber: payload.currentPage,
    pageSize: payload.pageSize,
    totalItems: payload.totalRecords,
    totalPages: totalPages,
    hasNextPage: payload.currentPage < totalPages,
    hasPrevPage: payload.currentPage > 1,
    links: {
      self: "/api/v1/assets?page=" ++ (payload.currentPage as String),
      next: if (payload.currentPage < totalPages) "/api/v1/assets?page=" ++ ((payload.currentPage + 1) as String) else null,
      prev: if (payload.currentPage > 1) "/api/v1/assets?page=" ++ ((payload.currentPage - 1) as String) else null
    }
  },
  data: payload.records
}

